using Erp.Abstractions.Events;
using Erp.ModuleSystem;
using Erp.Modules.Purchasing;
namespace Erp.UnitTests; public sealed class PurchasingModuleTests { [Fact] public void ManifestDeclaresDependenciesPermissionsAndEvents() { var m = new PurchasingModule(); var p = new PermissionRegistry(); var e = new Registry(); m.ConfigurePermissions(p); m.ConfigureIntegrationEvents(e); Assert.Equal(["erp.contacts", "erp.products"], m.Manifest.Dependencies.Select(x => x.ModuleId)); Assert.Equal(5, p.Permissions.Count); Assert.Equal(3, e.Events.Count); } [Fact] public void ServerCalculatesPurchaseLineTotals() { Assert.Equal((20m, 2m, 0.9m, 18.9m), PurchaseOrderService.CalculateLine(2, 10, 10, 5)); } [Fact] public void InvalidLineIsRejected() => Assert.Throws<PurchasingValidationException>(() => PurchaseOrderService.CalculateLine(0, 1, 0, 0)); private sealed class Registry : IIntegrationEventRegistry { private readonly List<IntegrationEventDefinition> _events = []; public IReadOnlyCollection<IntegrationEventDefinition> Events => _events; public void Add<T>(string type) where T : IIntegrationEvent => _events.Add(new(type, typeof(T))); } }
